        first = path[1]
        entry = ((hop_count, cost, bandwidth, latency), list(path))
        cur = best.get(dest)
        if cur is None or q < cur[0]:
            best[dest] = (q, {first: entry})
        elif q == cur[0]:
            hops = cur[1]
            old = hops.get(first)
